class LoadError extends Error {
  constructor(message, status = null) {
    super(message);
    this.name = "LoadError";
    this.status = status;
  }
}

const sleep = ms => new Promise(r => setTimeout(r, ms));

function createLoader({ fetcher = fetch, retries = 2, limit = 3, timeoutMs = 1000 } = {}) {
  const cache = new Map();
  const running = new Map();
  const counts = { requests: 0, cacheHits: 0, failures: 0 };

  async function attempt(url) {
    counts.requests++;
    let timer;
    const timeout = new Promise((_, reject) => {
      timer = setTimeout(() => reject(new LoadError(`${url}: timed out`)), timeoutMs);
    });
    try {
      let response;
      try {
        response = await Promise.race([fetcher(url), timeout]);
      } catch (err) {
        throw err instanceof LoadError ? err : new LoadError(`${url}: ${err.message}`);
      }
      if (!response.ok) throw new LoadError(`${url}: HTTP ${response.status}`, response.status);
      try {
        return await response.json();
      } catch (err) {
        throw new LoadError(`${url}: bad JSON`, response.status);
      }
    } finally {
      clearTimeout(timer);
    }
  }

  const retryable = err => err.status === null || err.status === 429 || err.status >= 500;

  async function load(url) {
    for (let i = 0; ; i++) {
      try {
        return await attempt(url);
      } catch (err) {
        if (i >= retries || !retryable(err)) throw err;
        await sleep(10 * 2 ** i);
      }
    }
  }

  function get(url) {
    if (cache.has(url)) { counts.cacheHits++; return Promise.resolve(cache.get(url)); }
    if (running.has(url)) { counts.cacheHits++; return running.get(url); }
    const promise = load(url).then(
      data => { cache.set(url, data); running.delete(url); return data; },
      err => { counts.failures++; running.delete(url); throw err; },
    );
    running.set(url, promise);
    return promise;
  }

  async function getMany(urls) {
    const results = new Array(urls.length);
    let next = 0;
    async function worker() {
      while (next < urls.length) {
        const i = next++;
        const url = urls[i];
        try {
          results[i] = { url, ok: true, data: await get(url) };
        } catch (err) {
          results[i] = { url, ok: false, error: err.message };
        }
      }
    }
    await Promise.all(Array.from({ length: Math.min(limit, urls.length) }, worker));
    return results;
  }

  return { get, getMany, stats: () => ({ ...counts }) };
}

