const pause = ms => new Promise(r => setTimeout(r, ms));
const respond = (status, body) => ({ ok: status >= 200 && status < 300, status, json: async () => (typeof body === "string" ? JSON.parse(body) : body) });

function fakeServer(routes) {
  const server = { log: [], active: 0, peak: 0 };
  server.fetcher = async url => {
    server.log.push(url);
    server.active++;
    server.peak = Math.max(server.peak, server.active);
    try {
      await pause(5);
      const route = routes[url];
      if (route === undefined) return respond(404, null);
      return typeof route === "function" ? await route() : route;
    } finally {
      server.active--;
    }
  };
  return server;
}

async function rejection(promise) {
  try { await promise; } catch (e) { return e; }
  throw new Error("expected the promise to reject");
}

test("get and cache", async () => {
  const s = fakeServer({ "/a": respond(200, { x: 1 }) });
  const loader = createLoader({ fetcher: s.fetcher });
  checkEq(await loader.get("/a"), { x: 1 });
  checkEq(await loader.get("/a"), { x: 1 });
  checkEq(s.log, ["/a"]);
  checkEq(loader.stats(), { requests: 1, cacheHits: 1, failures: 0 });
});

test("a running load is shared", async () => {
  const s = fakeServer({ "/a": respond(200, [1, 2]) });
  const loader = createLoader({ fetcher: s.fetcher });
  const [one, two] = await Promise.all([loader.get("/a"), loader.get("/a")]);
  checkEq([one, two], [[1, 2], [1, 2]]);
  checkEq(s.log.length, 1);
  checkEq(loader.stats().cacheHits, 1);
});

test("404 fails at once and is not cached", async () => {
  const s = fakeServer({});
  const loader = createLoader({ fetcher: s.fetcher });
  const e = await rejection(loader.get("/missing"));
  check(e instanceof LoadError, "should be a LoadError");
  checkEq([e.name, e.message, e.status], ["LoadError", "/missing: HTTP 404", 404]);
  checkEq(s.log.length, 1);
  await rejection(loader.get("/missing"));
  checkEq(loader.stats(), { requests: 2, cacheHits: 0, failures: 2 });
});

test("server errors are retried", async () => {
  let calls = 0;
  const s = fakeServer({
    "/flaky": () => (++calls < 3 ? respond(503, null) : respond(200, '"ok"')),
    "/down": respond(500, null),
  });
  const loader = createLoader({ fetcher: s.fetcher });
  const t = Date.now();
  checkEq(await loader.get("/flaky"), "ok");
  check(Date.now() - t >= 30, "should wait 10 ms and 20 ms before the retries");
  checkEq(calls, 3);
  const e = await rejection(loader.get("/down"));
  checkEq([e.message, e.status], ["/down: HTTP 500", 500]);
  checkEq(loader.stats(), { requests: 6, cacheHits: 0, failures: 1 });
});

test("network errors and 429 are retried", async () => {
  const s = fakeServer({ "/net": () => { throw new TypeError("network down"); }, "/busy": respond(429, null) });
  const loader = createLoader({ fetcher: s.fetcher, retries: 1 });
  const e = await rejection(loader.get("/net"));
  checkEq([e.message, e.status], ["/net: network down", null]);
  await rejection(loader.get("/busy"));
  checkEq(s.log, ["/net", "/net", "/busy", "/busy"]);
});

test("timeouts", async () => {
  const s = fakeServer({ "/slow": async () => { await pause(150); return respond(200, {}); } });
  const loader = createLoader({ fetcher: s.fetcher, retries: 0, timeoutMs: 20 });
  const t = Date.now();
  const e = await rejection(loader.get("/slow"));
  checkEq([e.message, e.status], ["/slow: timed out", null]);
  check(Date.now() - t < 100, "should give up after about 20 ms");
});

test("bad JSON is not retried", async () => {
  const s = fakeServer({ "/bad": respond(200, "{oops") });
  const loader = createLoader({ fetcher: s.fetcher });
  const e = await rejection(loader.get("/bad"));
  checkEq([e.message, e.status], ["/bad: bad JSON", 200]);
  checkEq(s.log.length, 1);
});

test("getMany keeps order and the limit", async () => {
  const routes = {};
  for (let i = 1; i <= 6; i++) routes[`/${i}`] = respond(200, i * 10);
  const s = fakeServer(routes);
  const loader = createLoader({ fetcher: s.fetcher, limit: 2 });
  const results = await loader.getMany(["/1", "/2", "/x", "/3", "/4", "/5", "/6"]);
  checkEq(results.map(r => (r.ok ? r.data : r.error)), [10, 20, "/x: HTTP 404", 30, 40, 50, 60]);
  checkEq(results[2], { url: "/x", ok: false, error: "/x: HTTP 404" });
  checkEq(s.peak, 2);
  checkEq(await loader.getMany([]), []);
});

test("stats is a copy", async () => {
  const loader = createLoader({ fetcher: fakeServer({}).fetcher });
  const st = loader.stats();
  st.requests = 99;
  checkEq(loader.stats().requests, 0);
});

